function clean(text) {
  if (!text) return '';

  return text
    .replace(/\s+/g, ' ')
    .replace(/\u0000/g, '')
    .trim();
}

const REPEATED_LINE_MIN_COUNT = 3;
const REPEATED_LINE_MAX_LENGTH = 30;

function isUppercaseFragment(line) {
  const letters = line.replace(/[^A-Za-zÁÉÍÓÚÑÜáéíóúñü]/g, '');
  if (!letters) return false;
  return letters === letters.toUpperCase() && letters !== letters.toLowerCase();
}

function stripRepeatedLineFragments(texts) {
  const freq = new Map();

  for (const t of texts) {
    const raw = t.text || t.orig || '';
    if (!raw.includes('\r\n') && !raw.includes('\n')) continue;

    for (const rawLine of raw.split(/\r\n|\n/)) {
      const line = rawLine.trim();
      if (!line || line.length > REPEATED_LINE_MAX_LENGTH) continue;
      if (!isUppercaseFragment(line)) continue;
      freq.set(line, (freq.get(line) || 0) + 1);
    }
  }

  const noisyLines = new Set(
    [...freq.entries()]
      .filter(([, count]) => count >= REPEATED_LINE_MIN_COUNT)
      .map(([line]) => line)
  );

  if (noisyLines.size === 0) return texts;

  return texts.map(t => {
    const raw = t.text || t.orig || '';
    if (!raw.includes('\r\n') && !raw.includes('\n')) return t;

    const kept = raw
      .split(/\r\n|\n/)
      .filter(rawLine => !noisyLines.has(rawLine.trim()))
      .join(' ');

    return { ...t, text: kept };
  });
}

function extractTexts(doc) {
  const texts = [];
  const rawTexts = stripRepeatedLineFragments(doc.texts || []);

  for (const t of rawTexts) {
    const text = clean(t.text || t.orig);

    if (!text) continue;

    texts.push({
      type: t.label || 'text',
      text,
      page: t.prov?.[0]?.page_no || null,
      contentLayer: t.content_layer || 'body'
    });
  }

  return texts;
}

function extractTables(doc) {
  const tables = [];

  for (const table of doc.tables || []) {

    const grid = table?.data?.grid;

    if (!Array.isArray(grid)) {
      continue;
    }

    const rows = [];

    for (const row of grid) {

      if (!Array.isArray(row)) {
        continue;
      }

      const cells = row.map(cell => {
        return clean(cell?.text || '');
      });

      // evitar filas vacías
      if (cells.some(Boolean)) {
        rows.push(cells);
      }
    }

    tables.push({
      label: table.label || 'table',
      page: table.prov?.[0]?.page_no || null,
      contentLayer: table.content_layer || 'body',
      rows
    });
  }

  return tables;
}

function buildMarkdownTable(rows) {
  if (!rows?.length) return '';

  const md = [];

  for (const row of rows) {
    md.push(`| ${row.join(' | ')} |`);
  }

  return md.join('\n');
}

function buildChunks(doc) {

  const chunks = [];

  // TEXTS
  const texts = extractTexts(doc);

  for (const t of texts) {
    chunks.push({
      type: t.type,
      page: t.page,
      contentLayer: t.contentLayer,
      content: t.text
    });
  }

  // TABLES
  const tables = extractTables(doc);

  for (const table of tables) {

    chunks.push({
      type: 'table',
      page: table.page,
      contentLayer: table.contentLayer,
      content: buildMarkdownTable(table.rows),
      rows: table.rows
    });
  }

  return chunks;
}

// =========================
// MAIN
// =========================

const raw =
  $input.first().json.document?.json_content ||
  $input.first().json.json_content ||
  $input.first().json;

const doc =
  typeof raw === 'string'
    ? JSON.parse(raw)
    : raw;

const chunks = buildChunks(doc);

return [{
  json: {
    totalChunks: chunks.length,
    chunks
  }
}];

// ========================================
// CLEANUP NODE
// ========================================

const input = items[0].json.chunks || items[0].json;

// --------------------------------------------------
// CONFIG (generico -- no depende de ninguna compania/edicion concreta)
// --------------------------------------------------

const MIN_CONTENT_LENGTH = 3;

const REMOVE_PATTERNS = [
  /^\(contin[uú]a en la p[aá]g/i,
  /^\d{1,4}$/,
  /^\(\w+\)$/,
];

const BOILERPLATE_MIN_PAGES = 3;
const BOILERPLATE_MAX_LENGTH = 120;

// --------------------------------------------------
// HELPERS
// --------------------------------------------------

function normalizeText(text) {
  return text
    .replace(/\s+/g, " ")
    .replace(/­/g, "") // soft hyphen
    .replace(/\s+([.,;:])/g, "$1")
    .trim();
}

function shouldRemoveChunk(chunk) {
  if (!chunk.content) return true;

  // Docling ya distingue contenido real ("body") de cabeceras/pies/decoracion ("furniture")
  if (chunk.contentLayer && chunk.contentLayer !== "body") {
    return true;
  }

  const text = chunk.content.trim();

  if (text.length < MIN_CONTENT_LENGTH) {
    return true;
  }

  for (const pattern of REMOVE_PATTERNS) {
    if (pattern.test(text)) {
      return true;
    }
  }

  return false;
}

function removeRepeatedBoilerplate(chunks) {
  const pagesByText = new Map();

  for (const c of chunks) {
    if (c.content.length > BOILERPLATE_MAX_LENGTH) continue;

    if (!pagesByText.has(c.content)) {
      pagesByText.set(c.content, new Set());
    }
    pagesByText.get(c.content).add(c.page);
  }

  return chunks.filter(c => {
    if (c.content.length > BOILERPLATE_MAX_LENGTH) return true;

    const pages = pagesByText.get(c.content);
    return !(pages && pages.size >= BOILERPLATE_MIN_PAGES);
  });
}

// --------------------------------------------------
// MAIN
// --------------------------------------------------

const step1 = [];

for (const chunk of input) {

  // remove invalid chunks
  if (shouldRemoveChunk(chunk)) {
    continue;
  }

  // normalize
  const content = normalizeText(chunk.content);

  if (!content) {
    continue;
  }

  step1.push({
    type: chunk.type,
    page: chunk.page,
    content
  });
}

const cleaned = removeRepeatedBoilerplate(step1);

// --------------------------------------------------
// OUTPUT
// --------------------------------------------------

return [
  {
    json: {
      totalChunks: cleaned.length,
      chunks: cleaned
    }
  }
];

// =====================================================
// HIERARCHY BUILDER
// n8n Code Node
// =====================================================

const input = $input.first().json;

const chunks = input.chunks || [];

const hierarchy = [];
const stack = [];

// =====================================================
// HELPERS
// =====================================================

function normalize(text) {
  return (text || "")
    .replace(/\s+/g, " ")
    .trim();
}

// ¿Usa este documento la convención "Artículo Nº" (o "Artículo Preliminar")
// como división de máximo nivel? No todas las compañías la usan -- p.ej.
// Occident numera sus divisiones principales como "7. Título", sin ningún
// "Artículo" en todo el documento. Se detecta una sola vez, sobre el
// listado plano de chunks, antes de construir la jerarquía.
// "Art[ií]culo" (con o sin tilde) a propósito: una extracción con OCR
// degradada puede perder tildes (ya visto con Axa/force_ocr y con una
// captura antigua de Generali) -- si esta detección fuera sensible al
// acento, esa degradación haría caer TODO el documento al modo "sin
// convención de Artículo", desplazando el nivel de cada encabezado.
const HAS_ARTICLE_CONVENTION = chunks.some(chunk =>
  /^Art[ií]culo\s+\S/i.test(normalize(chunk.content))
);

// =====================================================
// INDICE / TABLA DE CONTENIDOS DEL DOCUMENTO
// =====================================================
// Hallazgo real (Allianz, 30/07): la heuristica de deteccion de nivel por
// numeracion/longitud de titulo no tiene forma de distinguir un capitulo
// real sin numerar (p.ej. "Determinacion de la indemnizacion") de una
// subseccion sin numerar dentro de un capitulo ya abierto -- si el
// capitulo real aparece profundo en la pila (nivel >= 4), la heuristica
// relativa nunca lo resetea a nivel 1, y todo el resto del documento
// queda mal anidado bajo el ultimo capitulo numerado real (visto en
// produccion: 65 de 66 unidades semanticas de un tramo de 10 paginas de
// Allianz quedaron atribuidas a la garantia equivocada). La mayoria de
// condicionados reales traen un indice/tabla de contenidos que Docling
// captura como chunk de tipo "table" y que hoy no se usaba para nada --
// se usa aqui como fuente de verdad para el reset a nivel 1 cuando existe.

function parseIndiceEntries(tableChunks) {
  const entries = [];

  // Patron A: filas "limpias" |Titulo|Pagina| (Allianz, Generali)
  const patternA = /\|\s*([^|]+?)\s*\|\s*(\d{1,4})\s*\|/g;

  // Patron B: titulo + puntos de relleno + pagina, con o sin celda propia
  // (Axa: "Titulo.......... |.48 |" o "Titulo..........48 |")
  const patternB = /\|\s*([^|]+?)\.{2,}\s*\|?\.?\s*(\d{1,4})\s*\|/g;

  for (const t of tableChunks) {

    const seenInThisTable = new Set();

    for (const re of [patternB, patternA]) {
      re.lastIndex = 0;
      let m;
      while ((m = re.exec(t.content))) {

        let title = m[1]
          .replace(/\.{2,}/g, "")
          .replace(/\s+/g, " ")
          .trim();

        const page = Number(m[2]);

        if (!title || title.length < 3) continue;
        if (/^\d+$/.test(title)) continue;

        const key = title.toLowerCase() + "|" + page;

        if (seenInThisTable.has(key)) continue;
        seenInThisTable.add(key);

        entries.push({ title, page });
      }
    }
  }

  // orden por pagina (el orden de aparicion en la tabla ya deberia ser
  // este, pero por si el patron A/B duplican en distinto orden)
  entries.sort((a, b) => a.page - b.page);

  return entries;
}

// Tolerancia a numeros romanos vs arabigos en titulos estructurales
// (caso real, Divina Seguros 27/08: el indice dice "ANEXO I" y el propio
// section_header del cuerpo dice "ANEXO 1" para el mismo anexo -- el PDF
// origen usa dos convenciones numericas distintas entre indice y cuerpo).
// Solo convierte un numeral romano bien formado cuando aparece justo
// despues de una palabra estructural conocida (anexo/capitulo/titulo/
// parte/apartado), para no arriesgarse a confundir una palabra corta
// cualquiera ("vi", "mi"...) en cualquier otro punto del titulo.
const STRUCTURAL_ROMAN_NUMERAL_RE = /\b(anexo|capitulo|titulo|parte|apartado)\s+([ivxlcdm]+)\b/g;
const STRICT_ROMAN_NUMERAL_RE = /^m{0,4}(cm|cd|d?c{0,3})(xc|xl|l?x{0,3})(ix|iv|v?i{0,3})$/;

function romanToArabic(roman) {
  const VALUES = { i: 1, v: 5, x: 10, l: 50, c: 100, d: 500, m: 1000 };
  let total = 0;
  for (let idx = 0; idx < roman.length; idx++) {
    const curr = VALUES[roman[idx]];
    const next = VALUES[roman[idx + 1]];
    total += (next && curr < next) ? -curr : curr;
  }
  return total;
}

function normalizeStructuralRomanNumerals(text) {
  return text.replace(STRUCTURAL_ROMAN_NUMERAL_RE, (match, keyword, numeral) => {
    if (!numeral || !STRICT_ROMAN_NUMERAL_RE.test(numeral)) return match;
    const value = romanToArabic(numeral);
    if (!value || value > 99) return match;
    return `${keyword} ${value}`;
  });
}

function normalizeForMatch(text) {
  const base = (text || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return normalizeStructuralRomanNumerals(base);
}

// Tolerancia a palabras funcionales ausentes/presentes entre indice y
// cuerpo (caso real: indice "Vehiculos segunda categoria" vs cuerpo
// "Vehiculos DE segunda categoria", Divina Seguros 27/08). Ultimo
// recurso, tras los demas: exige al menos 3 palabras con contenido real
// para no reabrir el falso positivo ya conocido de titulos cortos
// genericos (ver nota de "Asistencia" mas abajo).
const TITLE_STOPWORDS = new Set(["de", "del", "la", "el", "los", "las", "y", "en", "a", "al"]);

function significantTokens(normalized) {
  return normalized.split(" ").filter(tok => tok && !TITLE_STOPWORDS.has(tok));
}

function significantTokensContained(na, nb) {
  const [shortStr, longStr] = na.length <= nb.length ? [na, nb] : [nb, na];
  const shortTokens = significantTokens(shortStr);
  const longTokens = new Set(significantTokens(longStr));
  if (shortTokens.length < 3) return false;
  return shortTokens.every(tok => longTokens.has(tok));
}

function titlesMatch(a, b) {

  const na = normalizeForMatch(a);
  const nb = normalizeForMatch(b);

  if (!na || !nb) return false;
  if (na === nb) return true;

  // Contencion (el indice suele truncar o el cuerpo añade sufijos como
  // ":"/numeros) -- exige que la cadena corta sea una parte sustancial de
  // la larga: un titulo de indice corto (p.ej. "Asistencia") no debe
  // casar por pura casualidad contra un titulo de cuerpo mucho mas largo
  // que solo contiene esa palabra de forma incidental (visto en Generali
  // real: indice "Asistencia" vs. subseccion decimal "4.8. Asistencia en
  // la redaccion y revision de contratos de arrendamiento").
  const MIN_CONTAINMENT_RATIO = 0.6;
  if (na.length >= 6 && nb.includes(na) && na.length / nb.length >= MIN_CONTAINMENT_RATIO) return true;
  if (nb.length >= 6 && na.includes(nb) && nb.length / na.length >= MIN_CONTAINMENT_RATIO) return true;

  // Tolerancia a letra capitular perdida en la extraccion del indice
  // (visto en Generali real: "bjeto..." en vez de "Objeto...").
  for (let k = 1; k <= 3; k++) {
    if (na.length > k + 5 && nb.length > k + 5) {
      if (na.slice(k) === nb.slice(0, na.length - k)) return true;
      if (nb.slice(k) === na.slice(0, nb.length - k)) return true;
    }
  }

  if (significantTokensContained(na, nb)) return true;

  return false;
}

const tableChunks = chunks.filter(chunk => chunk.type === "table");
const indiceEntries = parseIndiceEntries(tableChunks);
const HAS_INDICE = indiceEntries.length >= 3;

let indiceCursor = 0;
// Pagina del ultimo capitulo de nivel 1 confirmado por el indice --
// permite distinguir, una vez agotado el indice, entre "seguimos
// dentro del ultimo capitulo anclado" (Divina real: ANEXO II es la
// ultima entrada del indice y el documento termina 2 paginas despues)
// y "esto ya es territorio nuevo sin listar" (Axa real: el indice
// termina y el documento sigue con un capitulo entero -- Consorcio de
// Compensacion de Seguros -- muchas paginas mas alla).
let lastMatchedIndicePage = null;
const INDICE_EXHAUSTED_TAIL_TOLERANCE_PAGES = 15;
const INDICE_LOOKAHEAD = 4;
const INDICE_PAGE_TOLERANCE_BEFORE = 1;
const INDICE_PAGE_TOLERANCE_AFTER = 3;

// Devuelve true (y avanza el cursor) si esta cabecera real del cuerpo
// coincide con la siguiente entrada -- o alguna de las proximas, por si
// una entrada del indice nunca aparece como section_header propio en el
// cuerpo -- dentro de una ventana de paginas razonable.
function matchesIndiceTopLevel(headerText, page) {

  if (!HAS_INDICE) return false;

  // Una subseccion con numeracion decimal propia ("4.8. Titulo") ya
  // declara por si misma que es hija de un capitulo numerado -- nunca
  // puede ser el inicio de un capitulo real, aunque su texto casualmente
  // contenga una palabra de una entrada del indice (visto en Generali
  // real, indice "Asistencia" vs. cuerpo "4.8. Asistencia en la
  // redaccion...").
  if (/^\d+\.\d+\.?\s/.test(normalize(headerText))) return false;

  for (let i = indiceCursor; i < Math.min(indiceEntries.length, indiceCursor + INDICE_LOOKAHEAD); i++) {

    const entry = indiceEntries[i];

    if (page != null && entry.page != null) {
      if (page < entry.page - INDICE_PAGE_TOLERANCE_BEFORE) continue;
      if (page > entry.page + INDICE_PAGE_TOLERANCE_AFTER) continue;
    }

    if (titlesMatch(headerText, entry.title)) {
      indiceCursor = i + 1;
      entry.matchedAtPage = page;
      lastMatchedIndicePage = page != null ? page : entry.page;
      return true;
    }
  }

  return false;
}

function detectLevel(content, previousLevel = 1, page = null) {

  const text = normalize(content);

  // ==========================================
  // LEVEL 1
  // Artículo Xº / Artículo Preliminar
  // ==========================================

  if (/^Art[ií]culo\s+\S/i.test(text)) {
    return 1;
  }

  // ==========================================
  // LEVEL 3 (o 2 si el documento no usa "Artículo")
  // 1.1. Título
  // ==========================================

  if (/^\d+\.\d+\.\s*/.test(text)) {
    return HAS_ARTICLE_CONVENTION ? 3 : 2;
  }

  // ==========================================
  // LEVEL 2 (o 1 si el documento no usa "Artículo")
  // 1. Título
  //
  // Si el documento no tiene ningún "Artículo Nº", esta numeración
  // simple es la división de máximo nivel (caso Occident), no una
  // subdivisión dentro de un artículo (caso Generali).
  //
  // Cuando el documento SI tiene indice real, este manda sobre esta
  // regla: una numeracion "N. Titulo" puede ser un capitulo real
  // (Occident, sin indice) o una sublista local dentro de un capitulo
  // sin numerar en el indice (Allianz real: "4. Urgencias de
  // cerrajeria" es el punto 4 de la garantia "Urgencias domesticas y
  // asistencia", no un capitulo propio) -- sin indice que lo confirme,
  // se trata como subseccion (nivel 2), nunca como capitulo nuevo.
  // Si el indice ya agoto todas sus entradas (no cubre el resto del
  // documento -- visto en Axa Hogar Protect real: el indice termina en
  // "Solucion de conflictos..." pero el documento sigue con el capitulo
  // del Consorcio de Compensacion de Seguros, que el indice no lista),
  // se deja de confiar en el y se vuelve al comportamiento heuristico
  // original como red de seguridad, en vez de aplanar para siempre todo
  // lo que venga despues bajo el ultimo capitulo confirmado.
  // ==========================================

  if (/^\d+\.\s+/.test(text)) {
    if (HAS_INDICE && indiceCursor < indiceEntries.length) {
      return 2;
    }
    // Indice agotado: si seguimos dentro de una ventana razonable de
    // paginas desde el ultimo capitulo anclado, seguimos anidando bajo el
    // (caso real Divina). Mas alla de esa ventana, se mantiene el fallback
    // original (caso real Axa) -- ver nota de lastMatchedIndicePage.
    if (
      HAS_INDICE &&
      lastMatchedIndicePage != null &&
      page != null &&
      page - lastMatchedIndicePage <= INDICE_EXHAUSTED_TAIL_TOLERANCE_PAGES
    ) {
      return 2;
    }
    return HAS_ARTICLE_CONVENTION ? 2 : 1;
  }

  // ==========================================
  // LEVEL 4
  // ¿Qué cubre?
  // ¿Qué no cubre?
  // ==========================================

  if (/^¿Qué/i.test(text)) {
    return 4;
  }

  // ==========================================
  // SEMANTIC TITLES
  // Coberturas sin numeración
  // ==========================================

  const words = text.split(" ").length;

  const looksLikeTitle =
    words <= 8 &&
    !text.endsWith(".") &&
    !text.startsWith("-");

  if (looksLikeTitle) {

    // Después de exclusiones/cobertura
    // normalmente empieza una nueva garantía
    if (previousLevel >= 4) {
      return 2;
    }

    return previousLevel + 1;
  }

  // ==========================================
  // DEFAULT
  // ==========================================

  return 99;
}

function createNode(chunk, overrides = {}) {

  const content = normalize(chunk.content);

  const baseLevel =
    chunk.level ||
    detectLevel(
      content,
      stack.length
        ? stack[stack.length - 1].level
        : 1,
      chunk.page
    );

  // OVERRIDE: si el indice confirma que esta cabecera es el inicio de un
  // capitulo real de nivel 1, manda sobre la heuristica generica -- asi
  // se cubre tanto el caso "la heuristica ya decia nivel 1 por
  // numeracion" (estan de acuerdo, no cambia nada) como el caso "la
  // heuristica lo anidaba mal por no tener numeracion" (el indice lo
  // corrige).
  const indiceOverride =
    matchesIndiceTopLevel(content, chunk.page);

  return {
    type: chunk.type,
    level: indiceOverride ? 1 : baseLevel,
    page: chunk.page || null,
    content,
    children: [],
    ...overrides
  };
}

// =====================================================
// MAIN LOOP
// =====================================================

for (const chunk of chunks) {

  let chunkType = chunk.type || "text";

  const chunkContent = normalize(chunk.content);

  // ===================================================
  // NORMALIZE "¿QUÉ..." AS HEADERS
  // incluso si vienen como list_item/text
  // ===================================================

  if (
    /^¿Qué/i.test(chunkContent)
  ) {
    chunkType = "section_header";
  }

  // ===================================================
  // NORMALIZE SEMANTIC HEADERS
  // ===================================================

  if (
    chunkType !== "section_header"
  ) {

    const words = chunkContent.split(" ").length;

    const looksLikeSemanticTitle =
      words <= 8 &&
      !chunkContent.endsWith(".") &&
      !chunkContent.startsWith("-");

    if (looksLikeSemanticTitle) {
      chunkType = "section_header";
    }
  }

  // ===================================================
  // SECTION HEADERS
  // ===================================================

  if (chunkType === "section_header") {

    // ==========================================
    // CASO:
    // "Título ¿Qué cubre?"
    // ==========================================

    const combinedMatch =
      chunkContent.match(
        /^(.*?)\s+(¿Qué(?:\s+no)?\s+cubre.*)$/i
      );

    if (combinedMatch) {

      const parentTitle =
        normalize(combinedMatch[1]);

      const childTitle =
        normalize(combinedMatch[2]);

      const parentIndiceOverride =
        matchesIndiceTopLevel(parentTitle, chunk.page);

      const parentNode = {
        type: "section_header",
        level: parentIndiceOverride
          ? 1
          : detectLevel(
              parentTitle,
              stack.length
                ? stack[stack.length - 1].level
                : 1,
              chunk.page
            ),
        page: chunk.page || null,
        content: parentTitle,
        children: []
      };

      const childNode = {
        type: "section_header",
        level: 4,
        page: chunk.page || null,
        content: childTitle,
        children: []
      };

      // ==========================================
      // CLEAN STACK
      // ==========================================

      while (
        stack.length > 0 &&
        stack[stack.length - 1].level >= parentNode.level
      ) {
        stack.pop();
      }

      // ==========================================
      // INSERT PARENT
      // ==========================================

      if (stack.length === 0) {
        hierarchy.push(parentNode);
      } else {
        stack[stack.length - 1]
          .children
          .push(parentNode);
      }

      // ==========================================
      // INSERT CHILD
      // ==========================================

      parentNode.children.push(childNode);

      // ==========================================
      // PUSH TO STACK
      // ==========================================

      stack.push(parentNode);
      stack.push(childNode);

      continue;
    }

    // ==========================================
    // NORMAL HEADER
    // ==========================================

    const node = createNode({
      ...chunk,
      type: chunkType
    });

    // ==========================================
    // CLEAN STACK
    // ==========================================

    while (
      stack.length > 0 &&
      stack[stack.length - 1].level >= node.level
    ) {
      stack.pop();
    }

    // ==========================================
    // INSERT NODE
    // ==========================================

    if (stack.length === 0) {
      hierarchy.push(node);
    } else {
      stack[stack.length - 1]
        .children
        .push(node);
    }

    // ==========================================
    // PUSH HEADER ONLY
    // ==========================================

    stack.push(node);

    continue;
  }

  // ===================================================
  // TEXT / LIST_ITEM / PARAGRAPH
  // ===================================================

  const leaf = {
    type: chunkType,
    page: chunk.page || null,
    content: chunkContent
  };

  if (stack.length === 0) {
    hierarchy.push(leaf);
  } else {
    stack[stack.length - 1]
      .children
      .push(leaf);
  }
}

// =====================================================
// DIAGNOSTICO DE COBERTURA DEL INDICE
// =====================================================
// Riesgo real observado (Axa Hogar Protect, condicionado antiguo,
// 30/07): el indice puede existir pero ser "grueso" -- agrupar todo un
// bloque real de garantias bajo una unica entrada tematica (p.ej. "¿Qué
// le cubre y qué no le cubre este seguro?"), dejando decenas de paginas
// sin ningun anclaje real de nivel 1. Sin la convencion "Artículo Nº"
// como red de seguridad, ese hueco queda mal atribuido al ultimo
// capitulo de indice confirmado en vez de tener su propio capitulo real
// -- el mismo bug de fondo que este nodo corrige, pero causado por un
// indice insuficiente en vez de por la ausencia total de indice. Este
// diagnostico no lo soluciona (exigiria heuristicas mas fragiles todavia
// menos detectables por otra persona en el futuro) -- lo hace visible en
// el artefacto final para revision humana, mismo criterio que
// rejected_dependencies/ungrounded_dependencies del Guardrail.
//
// Umbral de 10 paginas fijado con las 3 ejecuciones reales disponibles:
// Allianz (hueco maximo real 2 paginas, indice fiable) y Axa Hogar
// Protect (hueco maximo real 45 paginas sin convencion de Artículo, el
// caso real que motivo este diagnostico) quedan a lados opuestos del
// umbral con margen amplio. Generali tiene un hueco de 46 paginas pero
// SI tiene convencion de Artículo como red de seguridad real (confirmado
// sin regresiones offline, 8/285 unidades cambiadas, todas mejoras) --
// por eso el diagnostico exige la ausencia de esa convencion, no basta
// con mirar el hueco en paginas.
const INDICE_GAP_THRESHOLD_PAGES = 10;

const documentPages = chunks.map(chunk => chunk.page || 0);
const minDocumentPage = documentPages.length ? Math.min(...documentPages) : 0;
const maxDocumentPage = documentPages.length ? Math.max(...documentPages) : 0;

const matchedIndiceEntries = indiceEntries.filter(entry => entry.matchedAtPage != null);
const matchedIndicePages = matchedIndiceEntries
  .map(entry => entry.matchedAtPage)
  .sort((a, b) => a - b);

let maxUnanchoredPageGap = 0;
let previousAnchorPage = minDocumentPage;

for (const page of matchedIndicePages) {
  maxUnanchoredPageGap = Math.max(maxUnanchoredPageGap, page - previousAnchorPage);
  previousAnchorPage = page;
}

maxUnanchoredPageGap = Math.max(maxUnanchoredPageGap, maxDocumentPage - previousAnchorPage);

const indiceCoverageLow =
  HAS_INDICE &&
  !HAS_ARTICLE_CONVENTION &&
  maxUnanchoredPageGap > INDICE_GAP_THRESHOLD_PAGES;

// $getWorkflowStaticData("global") persiste dentro de la misma ejecucion
// y es accesible desde cualquier nodo de codigo del workflow sin
// necesidad de conexion explicita -- se usa aqui para que el diagnostico
// (calculado una unica vez, aqui, al principio del pipeline) llegue
// hasta "Build Coverage Matcher Contract" (al final, tras el bucle del
// LLM) sin tener que recablear los nodos de loop/merge intermedios.
const staticData = $getWorkflowStaticData("global");

staticData.indice_diagnostics = {
  has_indice: HAS_INDICE,
  has_article_convention: HAS_ARTICLE_CONVENTION,
  indice_entries_total: indiceEntries.length,
  indice_entries_matched: matchedIndiceEntries.length,
  max_unanchored_page_gap: maxUnanchoredPageGap,
  indice_coverage_low: indiceCoverageLow,
  unmatched_indice_entries: indiceEntries
    .filter(entry => entry.matchedAtPage == null)
    .map(entry => ({ page: entry.page, title: entry.title }))
};

// =====================================================
// OUTPUT
// =====================================================

return [
  {
    json: {
      hierarchy
    }
  }
];

// ============================================
// SEMANTIC ASSEMBLER
// n8n Code Node
// ============================================

const input = $input.first().json;

const hierarchy = input.hierarchy || [];

const semanticUnits = [];

let idCounter = 1;

// ============================================
// SECTION DETECTION
// ============================================

function detectSectionType(text = "") {

  const t = text.toLowerCase();

  if (/(qué no cubre|no cubre|exclusiones?)/i.test(t)) {
    return "exclusion";
  }

  if (/(qué cubre|coberturas?|garantías?)/i.test(t)) {
    return "coverage";
  }

  if (/(límites?|limitaciones?|sublímites?)/i.test(t)) {
    return "limit";
  }

  if (/(franquicias?|deducible)/i.test(t)) {
    return "deductible";
  }

  if (/(condiciones?|requisitos?)/i.test(t)) {
    return "condition";
  }

  if (/(ámbito territorial|territorial)/i.test(t)) {
    return "territorial_scope";
  }

  return null;
}

// ============================================
// COVERAGE HEADER DETECTION
// ============================================

function isCoverageHeader(text = "") {

  if (!text) {
    return false;
  }

  if (detectSectionType(text)) {
    return false;
  }

  const t = text.trim();

  // encabezados numerados
  if (/^\d+(\.\d+)*\.?\s+/.test(t)) {
    return true;
  }

  // encabezados típicos
  if (
    /(garantía|garantías|cobertura|coberturas|protección|asistencia)/i.test(t)
  ) {
    return true;
  }

  // encabezados cortos sin puntuación narrativa
  if (
    t.length < 120 &&
    !/[.;:]/.test(t)
  ) {
    return true;
  }

  return false;
}

// ============================================
// SECTION TARGET EXTRACTION
// ============================================

function extractSectionTarget(text = "") {

  const t = text.trim();

  let match;

  match = t.match(
    /^¿?\s*qué no cubre\s+(.+?)\??$/i
  );

  if (match) {
    return match[1].trim();
  }

  match = t.match(
    /^¿?\s*qué cubre\s+(.+?)\??$/i
  );

  if (match) {
    return match[1].trim();
  }

  return null;
}

// ============================================
// SEMANTIC TYPE DETECTION
// ============================================

function detectSemanticType(
  text = "",
  currentSection = null
) {

  const t = text.toLowerCase();

  if (
    /(no cubre|no quedan cubiertos|queda excluido|se excluye|esta cobertura no|no se garantiza)/i.test(t)
  ) {
    return "exclusion";
  }

  if (
    /(franquicia|deducible|a cargo del asegurado)/i.test(t)
  ) {
    return "deductible";
  }

  if (
    /(hasta|máximo|con el límite|no superior a|hasta un máximo)/i.test(t)
  ) {
    return "limit";
  }

  if (
    /(siempre que|cuando se asegure|en caso de|a condición de|si )/i.test(t)
  ) {
    return "condition";
  }

  if (
    /(siempre que esté contratada|requiere la contratación|solo si se incluye)/i.test(t)
  ) {
    return "dependency";
  }

  if (
    /(territorio|españa|unión europea|extranjero|ámbito territorial)/i.test(t)
  ) {
    return "territorial_scope";
  }

  if (
    /(deberá|será necesario|obligatorio|requiere)/i.test(t)
  ) {
    return "requirement";
  }

  if (currentSection) {
    return currentSection;
  }

  return "unknown";
}

// ============================================
// TEXT NORMALIZATION
// ============================================

function normalizeText(text) {

  return text
    .replace(/\s+/g, " ")
    .replace(/\s([.,;:])/g, "$1")
    .trim();
}

// ============================================
// EMIT SEMANTIC UNIT
// ============================================

function emitSemanticUnit(
  context,
  text,
  sourceHeaders = []
) {

  const normalized =
    normalizeText(text);

  if (!normalized) {
    return;
  }

  const semanticType =
    detectSemanticType(
      normalized,
      context.currentSection
    );

  semanticUnits.push({

    id:
      `su_${String(idCounter++).padStart(5, "0")}`,

    article:
      context.article || null,

    coverage_path:
      [...context.coveragePath],

    section:
      context.currentSection || "unknown",

    semantic_type:
      semanticType,

    text:
      normalized,

    source_headers:
      sourceHeaders,

    lineage: [
      context.article,
      ...context.coveragePath
    ].filter(Boolean),

    metadata: {

      contains_limits:
        semanticType === "limit",

      contains_conditions:
        semanticType === "condition",

      contains_exclusions:
        semanticType === "exclusion",

      word_count:
        normalized.split(/\s+/).length
    }
  });
}

// ============================================
// CONSOLIDATE TEXT CHILDREN
// ============================================

function consolidateTextNodes(children = []) {

  const blocks = [];

  let currentBlock = [];

  function flush() {

    if (currentBlock.length) {

      blocks.push({
        type: "text_block",
        content:
          currentBlock.join("\n")
      });

      currentBlock = [];
    }
  }

  for (const child of children) {

    if (
      child.type === "text" ||
      child.type === "paragraph"
    ) {
      currentBlock.push(child.content);
      continue;
    }

    if (
      child.type === "list_item"
    ) {

      currentBlock.push(
        `- ${child.content}`
      );

      continue;
    }

    flush();

    blocks.push(child);
  }

  flush();

  return blocks;
}

// ============================================
// DFS WALKER
// ============================================

function walk(
  node,
  parentContext = {}
) {

  const context = {

    article:
      parentContext.article || null,

    coveragePath: [
      ...(parentContext.coveragePath || [])
    ],

    currentSection:
      parentContext.currentSection || null
  };

  // ========================================
  // SECTION HEADER
  // ========================================

  if (
    node.type === "section_header"
  ) {

    const header =
      normalizeText(node.content);

    // Nivel 1 = division de maximo nivel del documento, calculada por
    // Hierarchy Builder -- puede ser "Articulo Nº" (Generali) o una
    // numeracion simple "N. Titulo" cuando el documento no usa "Articulo"
    // en absoluto (Occident). Usar el nivel ya calculado, no un regex
    // propio, evita mantener el mismo criterio duplicado en dos nodos.
    if (
      node.level === 1
    ) {
      context.article = header;
    }

    const detectedSection =
      detectSectionType(header);

    if (detectedSection) {

      context.currentSection =
        detectedSection;

      const target =
        extractSectionTarget(header);

      if (target) {

        const idx =
          context.coveragePath.findIndex(
            p =>
              p
                .toLowerCase()
                .includes(
                  target.toLowerCase()
                )
          );

        if (idx >= 0) {

          context.coveragePath =
            context.coveragePath.slice(
              0,
              idx + 1
            );
        }
      }

    } else {

      if (
        isCoverageHeader(header)
      ) {

        context.coveragePath.push(
          header
        );
      }
    }
  }

  // ========================================
  // CHILDREN
  // ========================================

  const children =
    consolidateTextNodes(
      node.children || []
    );

  for (const child of children) {

    if (
      child.type === "text_block"
    ) {

      emitSemanticUnit(
        context,
        child.content,
        [...context.coveragePath]
      );

      continue;
    }

    walk(child, context);
  }
}

// ============================================
// ROOT WALK
// ============================================

for (const node of hierarchy) {
  walk(node, {});
}

// ============================================
// OUTPUT
// ============================================

return [
  {
    json: {
      semantic_units:
        semanticUnits
    }
  }
];

// =====================================================
// ONTOLOGY EMBEDDING BUILDER
// n8n Code Node
// =====================================================

const input = $input.first().json;

const semanticUnits = input.semantic_units || [];

const embeddingDocuments = [];

// =====================================================
// HELPERS
// =====================================================

function normalize(text) {
  return (text || "")
    .replace(/\s+/g, " ")
    .trim();
}

function buildEmbeddingText(unit) {

  const parts = [];

  // ==========================================
  // ARTICLE
  // ==========================================

  if (unit.article) {
    parts.push(`Artículo: ${normalize(unit.article)}`);
  }

  // ==========================================
  // COVERAGE PATH
  // ==========================================

  if (
    Array.isArray(unit.coverage_path) &&
    unit.coverage_path.length > 0
  ) {
    parts.push(
      `Cobertura: ${unit.coverage_path.join(" > ")}`
    );
  }

  // ==========================================
  // SECTION
  // ==========================================

  if (unit.section) {
    parts.push(`Sección: ${unit.section}`);
  }

  // ==========================================
  // SEMANTIC TYPE
  // ==========================================

  if (unit.semantic_type) {
    parts.push(
      `Tipo semántico: ${unit.semantic_type}`
    );
  }

  // ==========================================
  // SOURCE HEADERS
  // ==========================================

  if (
    Array.isArray(unit.source_headers) &&
    unit.source_headers.length > 0
  ) {
    parts.push(
      `Headers: ${unit.source_headers.join(" > ")}`
    );
  }

  // ==========================================
  // LINEAGE
  // ==========================================

  if (
    Array.isArray(unit.lineage) &&
    unit.lineage.length > 0
  ) {
    parts.push(
      `Jerarquía: ${unit.lineage.join(" > ")}`
    );
  }

  // ==========================================
  // LEGAL TEXT
  // ==========================================

  if (unit.text) {
    parts.push(
      `Texto jurídico: ${normalize(unit.text)}`
    );
  }

  return parts.join("\n");
}

// =====================================================
// MAIN LOOP
// =====================================================

for (const unit of semanticUnits) {

  const embeddingText = buildEmbeddingText(unit);

  embeddingDocuments.push({

    id: unit.id,

    embedding_text: embeddingText,

    semantic_unit: unit

  });
}

// =====================================================
// OUTPUT
// =====================================================

return [
  {
    json: {
      total_documents: embeddingDocuments.length,
      embedding_documents: embeddingDocuments
    }
  }
];

const itemsOut = [];

/**
 * =========================================================
 * RULE CHUNKER v4.1 STABLE
 * =========================================================
 *
 * NUEVO:
 * ✔ excluyéndose → excludes
 * ✔ con exclusión de → excludes
 * ✔ únicamente → requires
 *
 * =========================================================
 *
 * OBJETIVO:
 * Crear chunks jurídicos coherentes y enriquecidos
 * para el extractor LLM.
 *
 * =========================================================
 */


// =========================================================
// CONFIG
// =========================================================

const MIN_CHUNK_LENGTH = 25;


// =========================================================
// HELPERS
// =========================================================

function cleanText(text) {

  return text
    .replace(/\s+/g, " ")
    .replace(/\n+/g, "\n")
    .trim();
}


// =========================================================
// SENTENCE SPLITTER
// =========================================================

function splitIntoSentences(text) {

  return text
    .split(
      /(?<=[.;:])\s+|\n+/g
    )
    .map(s => s.trim())
    .filter(Boolean);
}


// =========================================================
// BULLET SPLITTER
// =========================================================

function splitBullets(text) {

  const normalized =
    text
      .replace(/\s+-\s+/g, "\n- ")
      .replace(/\s+•\s+/g, "\n• ");

  const bulletRegex =
    /(?:^|\n)\s*[-•·▪◦]\s+/g;

  const hasBullets =
    bulletRegex.test(normalized);

  if (!hasBullets) {
    return [normalized];
  }

  return normalized
    .split(bulletRegex)
    .map(t => t.trim())
    .filter(t => t.length > 20);
}


// =========================================================
// ENUMERATION-AWARE LEGAL UNIT
// =========================================================

function isStandaloneLegalBullet(text) {

  const t = text.toLowerCase();

  // -------------------------------------------------------
  // limits
  // -------------------------------------------------------

  const hasLimit =
    /\b(hasta|maximo|máximo|mínimo)\b/i.test(t) ||
    /\b\d+[.,]?\d*\s?(€|euros|%)\b/i.test(t);

  // -------------------------------------------------------
  // conditions
  // -------------------------------------------------------

  const hasCondition =
    t.includes("siempre que") ||
    t.includes("a condición de") ||
    t.includes("condicionado a") ||
    t.includes("únicamente");

  // -------------------------------------------------------
  // exclusions
  // -------------------------------------------------------

  const hasNegation =
    t.includes("salvo") ||
    t.includes("no se aplica") ||
    t.includes("quedan excluidos") ||
    t.includes("con exclusión de") ||
    t.includes("excluyéndose");

  // -------------------------------------------------------
  // density
  // -------------------------------------------------------

  const longEnough =
    text.length > 60;

  const hasAnyLegalCue =
    hasLimit ||
    hasCondition ||
    hasNegation;

  if (!longEnough || !hasAnyLegalCue) {
    return false;
  }

  // -------------------------------------------------------
  // multi-clause detection
  // -------------------------------------------------------
  //
  // Un unico tipo de clausula juridica (aunque se repita) sigue
  // siendo un bloque atomico -- comportamiento original. Con >=2
  // tipos DISTINTOS (p.ej. condicion + exclusion), es prosa densa
  // con varias clausulas mezcladas: se delega en la division por
  // frase en vez de dejarlo como bloque unico (Fase 3 del plan;
  // caso real su_00233).
  //

  const distinctCueTypes = new Set(
    detectAllCues(text).filter(
      cue => cue !== "generic_rule"
    )
  );

  return distinctCueTypes.size <= 1;
}


// =========================================================
// LEGAL BOUNDARY DETECTION
// =========================================================

function startsNewLegalChunk(sentence) {

  const s = sentence.toLowerCase();

  return (

    s.startsWith("salvo ") ||

    s.startsWith("siempre que") ||

    s.startsWith("a condición de") ||

    s.startsWith("quedan excluidos") ||

    s.startsWith("no se cubre") ||

    s.startsWith("no se aplica") ||

    s.startsWith("con exclusión de") ||

    s.startsWith("excluyéndose") ||

    s.startsWith("hasta el") ||

    s.startsWith("hasta ") ||

    s.startsWith("máximo ") ||

    s.startsWith("mínimo ") ||

    s.startsWith("únicamente") ||

    /\b\d+[.,]?\d*\s?(€|euros|%)\b/i.test(s)

  );
}


// =========================================================
// MULTI-CUE DETECTION
// =========================================================

function detectAllCues(text) {

  const t = text.toLowerCase();

  const detected = [];

  // -------------------------------------------------------
  // NEGATION / EXCEPTION
  // -------------------------------------------------------

  if (
    t.includes("salvo") ||
    t.includes("a menos que")
  ) {
    detected.push("negation");
  }

  // -------------------------------------------------------
  // EXCLUSION
  // -------------------------------------------------------

  if (
    t.includes("quedan excluidos") ||
    t.includes("no se cubre") ||
    t.includes("no estarán cubiertos") ||
    t.includes("no quedará cubierta") ||
    t.includes("no se aplica") ||
    t.includes("con exclusión de") ||
    t.includes("excluyéndose") ||
    t.includes("excluidos")
  ) {
    detected.push("excludes");
  }

  // -------------------------------------------------------
  // REQUIRES
  // -------------------------------------------------------

  if (
    t.includes("siempre que") ||
    t.includes("a condición de") ||
    t.includes("condicionado a") ||
    t.includes("únicamente")
  ) {
    detected.push("requires");
  }

  // -------------------------------------------------------
  // TEMPORAL LIMIT
  // -------------------------------------------------------

  if (
    /\b(más de|menos de|inferior a|superior a)\s+\d+\s+(días|meses|años)\b/i.test(t)
  ) {
    detected.push("temporal_limit");
  }

  // -------------------------------------------------------
  // LIMIT
  // -------------------------------------------------------

  if (
    /\bhasta el\s+\d+/i.test(t) ||
    /\b\d+[.,]?\d*\s?(€|euros|%)\b/i.test(t)
  ) {
    detected.push("limit");
  }

  // -------------------------------------------------------
  // DEPENDENCY
  // -------------------------------------------------------

  if (
    t.includes("depende de") ||
    t.includes("supeditado")
  ) {
    detected.push("depends_on");
  }

  // -------------------------------------------------------
  // FALLBACK
  // -------------------------------------------------------

  if (detected.length === 0) {
    detected.push("generic_rule");
  }

  return detected;
}


// =========================================================
// PRIMARY CUE
// =========================================================

function computePrimaryCue(cues) {

  const precedence = {

    excludes: 100,

    negation: 95,

    temporal_limit: 90,

    limit: 80,

    requires: 70,

    depends_on: 60,

    generic_rule: 10
  };

  let bestCue = "generic_rule";

  let bestScore = 0;

  for (const cue of cues) {

    const score =
      precedence[cue] || 0;

    if (score > bestScore) {

      bestScore = score;

      bestCue = cue;
    }
  }

  return bestCue;
}


// =========================================================
// CHUNK TYPE
// =========================================================

function detectChunkType(primaryCue) {

  switch (primaryCue) {

    case "limit":
      return "limit_rule";

    case "temporal_limit":
      return "temporal_limit_rule";

    case "requires":
      return "condition_rule";

    case "excludes":
      return "exclusion_rule";

    case "negation":
      return "exception_rule";

    case "depends_on":
      return "dependency_rule";

    default:
      return "generic_rule";
  }
}


// =========================================================
// CHUNK PRIORITY
// =========================================================

function computeChunkPriority(
  allCues,
  text
) {

  let score = 1;

  // -------------------------------------------------------
  // cue density
  // -------------------------------------------------------

  score += allCues.length;

  // -------------------------------------------------------
  // exclusions
  // -------------------------------------------------------

  if (
    allCues.includes("excludes") ||
    allCues.includes("negation")
  ) {
    score += 3;
  }

  // -------------------------------------------------------
  // conditions
  // -------------------------------------------------------

  if (
    allCues.includes("requires")
  ) {
    score += 2;
  }

  // -------------------------------------------------------
  // limits
  // -------------------------------------------------------

  if (
    allCues.includes("limit") ||
    allCues.includes("temporal_limit")
  ) {
    score += 2;
  }

  // -------------------------------------------------------
  // numeric density
  // -------------------------------------------------------

  const numericMatches =
    text.match(/\d+/g) || [];

  score += Math.min(
    numericMatches.length,
    3
  );

  // -------------------------------------------------------
  // long chunks
  // -------------------------------------------------------

  if (text.length > 250) {
    score += 1;
  }

  return score;
}


// =========================================================
// CHUNK COMPLEXITY
// =========================================================

function detectChunkComplexity(allCues) {

  if (allCues.length >= 4) {
    return "nested";
  }

  if (allCues.length >= 2) {
    return "compound";
  }

  return "simple";
}


// =========================================================
// BUILD CHUNK
// =========================================================

function buildChunk(
  chunkText,
  semanticUnitId,
  chunkCounter
) {

  const cleanChunk =
    cleanText(chunkText);

  // -------------------------------------------------------
  // multi-cue detection
  // -------------------------------------------------------

  const allDetectedCues =
    detectAllCues(cleanChunk);

  const primaryCue =
    computePrimaryCue(allDetectedCues);

  const secondaryCues =
    allDetectedCues.filter(
      c => c !== primaryCue
    );

  return {

    chunk_id:
      `${semanticUnitId}_c${chunkCounter}`,

    chunk_type:
      detectChunkType(primaryCue),

    primary_cue:
      primaryCue,

    secondary_cues:
      secondaryCues,

    all_detected_cues:
      allDetectedCues,

    chunk_complexity:
      detectChunkComplexity(
        allDetectedCues
      ),

    chunk_priority:
      computeChunkPriority(
        allDetectedCues,
