for (const item of items) {

  const json = item.json;

  const su =
    json.semantic_unit || json;

  const semanticUnitId =
    json.semantic_unit_id ||
    su.id ||
    "unknown";

  const legalAnalysis =
    json.legal_cue_analysis || {};

  const text =
    cleanText(su.text || "");

  if (!text) {
    continue;
  }

  // =====================================================
  // BULLET SPLIT
  // =====================================================

  const bulletSections =
    splitBullets(text);

  const chunks = [];

  let chunkCounter = 1;

  // =====================================================
  // PROCESS BULLETS
  // =====================================================

  for (const bullet of bulletSections) {

    // ---------------------------------------------------
    // STANDALONE LEGAL BULLET
    // ---------------------------------------------------

    if (
      isStandaloneLegalBullet(bullet)
    ) {

      chunks.push(
        buildChunk(
          bullet,
          semanticUnitId,
          chunkCounter++
        )
      );

      continue;
    }

    // ===================================================
    // SENTENCE SPLIT
    // ===================================================

    const sentences =
      splitIntoSentences(bullet);

    let currentChunk = "";

    for (const sentence of sentences) {

      const shouldStartNewChunk =
        startsNewLegalChunk(sentence);

      // -------------------------------------------------
      // FLUSH
      // -------------------------------------------------

      if (
        shouldStartNewChunk &&
        currentChunk.length > 0
      ) {

        const chunkText =
          cleanText(currentChunk);

        if (
          chunkText.length >= MIN_CHUNK_LENGTH
        ) {

          chunks.push(
            buildChunk(
              chunkText,
              semanticUnitId,
              chunkCounter++
            )
          );
        }

        currentChunk = sentence;

      } else {

        currentChunk +=
          (currentChunk ? " " : "") +
          sentence;
      }
    }

    // ===================================================
    // FINAL FLUSH
    // ===================================================

    const finalChunk =
      cleanText(currentChunk);

    if (
      finalChunk &&
      finalChunk.length >= MIN_CHUNK_LENGTH
    ) {

      chunks.push(
        buildChunk(
          finalChunk,
          semanticUnitId,
          chunkCounter++
        )
      );
    }
  }

