// Fase 4 (Punto 1, CLAUDE.md §5.2): el matching ontologico ocurre a nivel
// de chunk, no de semantic unit completa -- reduce la contaminacion de
// contexto entre clausulas no relacionadas del mismo bloque.
const text =
  ($json.chunk?.text || "").toLowerCase();

const HIGH_SCORE_THRESHOLD = 0.80;
const MAX_MATCHES = 5;

// Ventana de proximidad (en caracteres) para decidir si una frase de
// negative_aliases "invalida" una aparicion concreta de un alias. No basta
// con que ambas frases esten en el mismo texto -- un mismo bloque puede
// contener un uso legitimo del alias Y, en otra parte, la frase de falso
// amigo (ver caso real su_00127: "sea propietario de..." legitimo, y mas
// adelante "comunidad de propietarios" como falso amigo, en el MISMO texto).
const NEGATIVE_ALIAS_PROXIMITY_WINDOW = 80;

function findAllIndices(haystack, needle) {
  const indices = [];
  let idx = haystack.indexOf(needle);
  while (idx !== -1) {
    indices.push(idx);
    idx = haystack.indexOf(needle, idx + 1);
  }
  return indices;
}

const matches = ($json.result || [])
  .map(item => {

    const payload = item.payload || {};

    const aliases = payload.aliases || [];
    const negativeAliases = payload.negative_aliases || [];

    const rawMatchedAliases = aliases.filter(alias =>
      text.includes(alias.toLowerCase())
    );

    const negativeAliasPositions =
      negativeAliases.flatMap(neg =>
        findAllIndices(text, neg.toLowerCase())
      );

    // Falso amigo lexico: un alias solo se suprime si TODAS sus
    // apariciones en el texto estan cerca de una frase de
    // negative_aliases -- si al menos una aparicion es "limpia"
    // (lejos de cualquier negative_alias), se conserva como match
    // legitimo (ver Fase 2/D.3 del plan).
    const matchedAliases =
      negativeAliasPositions.length === 0
        ? rawMatchedAliases
        : rawMatchedAliases.filter(alias => {

            const aliasPositions =
              findAllIndices(text, alias.toLowerCase());

            const allOccurrencesSuppressed =
              aliasPositions.length > 0 &&
              aliasPositions.every(aliasPos =>
                negativeAliasPositions.some(negPos =>
                  Math.abs(negPos - aliasPos) <
                    NEGATIVE_ALIAS_PROXIMITY_WINDOW
                )
              );

            return !allOccurrencesSuppressed;
          });

    const negativeAliasSuppressed =
      rawMatchedAliases.length > 0 &&
      matchedAliases.length === 0;

    const aliasMatch =
      matchedAliases.length > 0;

    const literalAliasEvidence =
      matchedAliases.length > 0;

    return {

      // ==================================================
      // Chunk lineage (Fase 4 / Punto 1)
      // ==================================================

      chunk_id:
        $json.chunk?.chunk_id || null,

      // ==================================================
      // Core ontology identity
      // ==================================================

      concept_id: payload.concept_id,
      concept_key: payload.concept_key,

      // ==================================================
      // Risk model
      // ==================================================

      risk_field: payload.risk_field,
      data_type: payload.data_type,

      // ==================================================
      // Ontology semantic information
      // ==================================================

      aliases: payload.aliases || [],

      contractual_examples:
        payload.contractual_examples || [],

      meaning:
        payload.meaning || null,

      interpretation:
        payload.interpretation || null,

      // ==================================================
      // Matching information
      // ==================================================

      score: item.score || 0,

      final_score:
        Number((item.score || 0).toFixed(3)),

      alias_match:
        aliasMatch,

      matched_aliases:
        matchedAliases,

      literal_alias_evidence:
        literalAliasEvidence,

      negative_alias_suppressed:
        negativeAliasSuppressed,

      raw_matched_aliases:
        rawMatchedAliases
    };
  });


// ========================================================
// GROUPS
// ========================================================

const aliasMatches =
  matches.filter(m =>
    m.alias_match
  );

const highScoreMatches =
  matches.filter(m =>
    !m.alias_match &&
    m.final_score >= HIGH_SCORE_THRESHOLD
  );


// ========================================================
// SORT
// ========================================================

aliasMatches.sort(
  (a, b) => b.final_score - a.final_score
);

highScoreMatches.sort(
  (a, b) => b.final_score - a.final_score
);


// ========================================================
// FINAL MATCHES
// ========================================================

const filteredMatches = [

  ...aliasMatches,

  ...highScoreMatches

]
.slice(0, MAX_MATCHES);


// ========================================================
// OUTPUT
// ========================================================

return {
  json: {

    ...$json,

    ontology_matches:
      filteredMatches,

    ontology_filter_stats: {

      original_matches:
        ($json.result || []).length,

      alias_matches:
