            m.alias_match,

          matched_aliases:
            m.matched_aliases,

          literal_alias_evidence:
            m.literal_alias_evidence,

          negative_alias_suppressed:
            m.negative_alias_suppressed

        })),

      debug_removed_matches:

        matches
          .filter(m =>
            !filteredMatches.some(f =>
              f.concept_id === m.concept_id
            )
          )
          .map(m => ({

