function boostConfidence(
  baseConfidence,
  semanticType,
  section,
  cueType
) {

  let boosted = baseConfidence;

  if (
    semanticType === "exclusion" &&
    (
      cueType === "excludes" ||
      cueType === "excludes_if" ||
      cueType === "negation"
    )
  ) {
    boosted += 0.05;
  }

  if (
    semanticType === "condition" &&
    cueType === "requires"
  ) {
    boosted += 0.04;
  }

  if (
    semanticType === "limit" &&
    (
      cueType === "limit" ||
      cueType === "temporal_limit"
    )
  ) {
    boosted += 0.05;
  }

  if (
    section === "territorial_scope" &&
    cueType === "limit"
  ) {
    boosted += 0.04;
  }

  return Number(Math.min(boosted, 0.99).toFixed(2));
}

function detectLimitSubtype(text) {

  const t = text.toLowerCase();

  if (
    t.includes("día") ||
    t.includes("días") ||
    t.includes("mes") ||
    t.includes("meses") ||
    t.includes("año") ||
    t.includes("años")
  ) {
    return "temporal_limit";
  }

  return "limit";
}

function hasOverlap(existingMatches, start, end) {

  return existingMatches.some(existing =>
    start < existing.end &&
    end > existing.start
  );
}

function hasNearbyStrongLimit(matches, start) {

  return matches.some(m =>
    (
      m.type === "limit" ||
      m.type === "temporal_limit"
    ) &&
    m.strength === "strong" &&
    Math.abs(m.start - start) < 25
  );
}

function hasNearbyNumericLimit(matches, start) {

  return matches.some(m =>
    (
      m.type === "limit" ||
      m.type === "temporal_limit"
    ) &&
    m.strength === "strong" &&
    Math.abs(m.start - start) < 60
  );
}

function detectComplexity(cueMatches) {

  const cueTypes = [
    ...new Set(cueMatches.map(c => c.type))
  ];

  const strongCueCount =
    cueMatches.filter(c => c.strength === "strong").length;

  if (
    cueTypes.includes("negation") &&
    cueTypes.length > 1
  ) {
    return "nested";
  }

  if (
    cueTypes.length > 1 ||
    strongCueCount > 1
  ) {
    return "compound";
  }

  return "simple";
}

function shouldCallLLM(
  cueMatches,
  semanticType,
  ontologyMatchCount
) {

  if (ontologyMatchCount === 0) {
    return false;
  }

  const cueTypes = [
    ...new Set(cueMatches.map(c => c.type))
  ];

  const hasApplicabilityCue =
    cueTypes.includes("requires") ||
    cueTypes.includes("excludes_if") ||
    cueTypes.includes("depends_on") ||
    cueTypes.includes("negation");

  const hasExclusionCue =
    cueTypes.includes("excludes");

  if (semanticType === "limit") {
    return hasApplicabilityCue;
  }

  if (semanticType === "deductible") {
    return hasApplicabilityCue;
  }

  if (semanticType === "exclusion") {
    return hasApplicabilityCue || hasExclusionCue;
  }

  const strongCues =
    cueMatches.filter(c => c.strength === "strong");

  if (strongCues.length > 0) {
    return true;
  }

  return cueTypes.length >= 2;
}

for (const item of items) {

  const su = item.json.semantic_unit || {};

  const text = su.text || "";
  const semanticType = su.semantic_type || "";
  const section = su.section || "";
  const coveragePath = su.coverage_path || [];
  const lineage = su.lineage || [];

  const cueMatches = [];

  for (const cue of cueDefinitions) {

    const matches = [...text.matchAll(cue.regex)];

    for (const match of matches) {

      const start = match.index;
      const end = start + match[0].length;

      if (
        hasOverlap(cueMatches, start, end)
      ) {
        continue;
      }

      let finalType = cue.type;

      if (cue.type === "limit") {
        finalType = detectLimitSubtype(match[0]);
      }

      if (
        finalType === "limit" &&
        cue.strength === "medium" &&
        (
          match[0].toLowerCase() === "máximo" ||
          match[0].toLowerCase() === "mínimo"
        ) &&
        hasNearbyNumericLimit(cueMatches, start)
      ) {
        continue;
      }

      if (
        finalType === "limit" &&
        cue.strength === "weak" &&
        hasNearbyStrongLimit(cueMatches, start)
      ) {
        continue;
      }

      cueMatches.push({

        type: finalType,

        strength: cue.strength,

        confidence: boostConfidence(
          cue.confidence,
          semanticType,
          section,
          finalType
        ),

        text: match[0],

        start,

        end
      });
    }
  }

  const cueTypes = [
    ...new Set(cueMatches.map(c => c.type))
  ];

  const hasApplicabilityCue =
    cueTypes.includes("requires") ||
    cueTypes.includes("excludes_if") ||
    cueTypes.includes("depends_on") ||
    cueTypes.includes("negation") ||
    cueTypes.includes("optional_if");

  const strongestConfidence =
