        item.json.unit_ontology_matches || [],

      ontology_match_count:
        ontologyMatchCount,

      legal_cue_analysis: {

        has_legal_cues:
          cueMatches.length > 0,

        has_applicability_cues:
          hasApplicabilityCue,

        cue_types: cueTypes,

        cue_matches: cueMatches,

        complexity:
          detectComplexity(cueMatches),

        cue_confidence:
          strongestConfidence,

        strong_cue_count:
          cueMatches.filter(
            c => c.strength === "strong"
          ).length,

        implicit_exclusion_candidate:
