// v21 (2026-09-03): mismo patron, para reglas de bonificacion/prima
// (Guardrail v21) -- hilado desde el primer despliegue.
const totalPremiumCalculationDependencies = artifacts.reduce(
  (sum, a) => sum + (a.premium_calculation_dependencies || []).length,
  0
);

// Calculado una unica vez en "Hierarchy Builder", al principio del
// pipeline -- viaja hasta aqui via workflow static data (sin recablear
// los nodos de loop/merge intermedios) para que quede dentro del
// contrato final, no en un fichero aparte que nadie mire (ver notas de
// "Hierarchy Builder" sobre el caso real de indice "grueso" de Axa
// Hogar Protect que motivo este diagnostico).
const staticData = $getWorkflowStaticData("global");
const indiceDiagnostics = staticData.indice_diagnostics || null;

return [{
  json: {

    schema_version: "1.0",

    generated_at:
      new Date().toISOString(),

    total_semantic_units:
      totalSemanticUnits,

    artifact_count:
      artifacts.length,

