    ...$json,
    filename: `coverage_matcher_contract_${timestamp}.json`
  }
}];

/**
 * Should Call LLM Filter
 *
 * Mantiene únicamente semantic units
 * marcadas por el Candidate Detector.
 */

return items.filter(item => {

  return (
    item.json.legal_cue_analysis?.should_call_llm === true
  );

});

/**
 * =========================================================
 * EXPLODE CHUNKS BY SEMANTIC UNIT v1
 * =========================================================
 *
 * Fase 4 del plan (Punto 1, CLAUDE.md §5.2): un item por chunk,
 * para que el matching ontologico (embeddings + Qdrant + alias-match)
 * ocurra a nivel de chunk en vez de a nivel de semantic unit completa.
 */

const itemsOut = [];

for (const item of items) {

  const json = item.json;

  const chunks = Array.isArray(json.chunks)
    ? json.chunks
    : [];

  for (const chunk of chunks) {

    itemsOut.push({
      json: {

        semantic_unit_id:
          json.semantic_unit_id,

        semantic_unit:
          json.semantic_unit,

        article:
          json.article,

        section:
          json.section,

        semantic_type:
          json.semantic_type,

        coverage_path:
          json.coverage_path || [],

        lineage:
          json.lineage || [],

        metadata:
          json.metadata || {},

        legal_cue_analysis:
          json.legal_cue_analysis || {},

        chunk_count:
          json.chunk_count || chunks.length,

        chunk
      }
    });
  }
}

return itemsOut;

/**
 * =========================================================
 * REGROUP CHUNKS BY SEMANTIC UNIT v1
 * =========================================================
 *
 * Fase 4 del plan (Punto 1, CLAUDE.md §5.2): reagrupa los chunks
 * (ya con su propio ontology_matches, calculado por Ontology Relevance
 * Filter a nivel de chunk) en un item por semantic unit, y calcula
 * ademas unit_ontology_matches: una union deduplicada por concept_id,
 * usada UNICAMENTE como gate de Coverage Dependency Candidate Detector
 * (equivalente al criterio de la topologia original) -- el LLM extractor
 * sigue viendo el ontology_matches acotado por chunk, no este agregado.
 */

const MAX_UNIT_MATCHES = 5;

const groups = new Map();

for (const item of items) {

  const json = item.json;
  const chunk = json.chunk || {};

  const chunkWithMatches = {
    ...chunk,
    ontology_matches: json.ontology_matches || []
  };

  if (!groups.has(json.semantic_unit_id)) {

    groups.set(json.semantic_unit_id, {

      semantic_unit_id:
        json.semantic_unit_id,

      semantic_unit:
        json.semantic_unit,

      article:
        json.article,

      section:
        json.section,

      semantic_type:
        json.semantic_type,

      coverage_path:
        json.coverage_path || [],

      lineage:
        json.lineage || [],

      metadata:
        json.metadata || {},

      legal_cue_analysis:
        json.legal_cue_analysis || {},

      chunks: []
    });
  }

  groups.get(json.semantic_unit_id).chunks.push(chunkWithMatches);
}

const itemsOut = [];

for (const group of groups.values()) {

  const allMatches = group.chunks.flatMap(
    c => c.ontology_matches || []
  );

  const byConceptId = new Map();

  for (const match of allMatches) {

    const existing = byConceptId.get(match.concept_id);

    if (!existing) {
      byConceptId.set(match.concept_id, match);
      continue;
    }

    // Preferir alias_match=true sobre false; a igualdad, mayor score.
    const better =
      (match.alias_match && !existing.alias_match) ||
      (
        match.alias_match === existing.alias_match &&
        (match.final_score || 0) > (existing.final_score || 0)
      );

    if (better) {
      byConceptId.set(match.concept_id, match);
    }
  }

  const unitOntologyMatches =
    [...byConceptId.values()]
      .sort((a, b) => {
        if (a.alias_match !== b.alias_match) {
          return a.alias_match ? -1 : 1;
        }
        return (b.final_score || 0) - (a.final_score || 0);
      })
      .slice(0, MAX_UNIT_MATCHES);

  itemsOut.push({
    json: {
      ...group,
      chunk_count: group.chunks.length,
      unit_ontology_matches: unitOntologyMatches
    }
  });
}

return itemsOut;

